// Your customers. One entry per company number.
// id: the company number (spaces, dots, dashes and a country prefix are ignored)
// country: optional ISO code - leave it out to match the number in any country
// ref: optional - your own customer reference, copied to each match
return [
  { json: { ref: 'cust-1', country: 'PL', id: '5260250995' } },
  { json: { ref: 'cust-2', country: 'BE', id: '0447.103.385' } },
];

// Where the last scheduled run stopped. 0 = from the beginning.
const state = $getWorkflowStaticData('global');
return [{ json: { since: state.cursor ?? 0 } }];

// Compare the downloaded feed pages with your list. Nothing here leaves n8n.
const norm = (v) => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const variants = (value, country) => {
  const base = norm(value);
  if (!base) return [];
  const out = new Set([base]);
  const m = /^([A-Z]{2})(\d.*)$/.exec(base);
  if (m && (!country || m[1] === country)) out.add(m[2]);
  for (const v of [...out]) { const t = v.replace(/^0+(?=.)/, ''); if (t) out.add(t); }
  return [...out];
};

const index = new Map();
for (const item of $('Your customer list').all()) {
  const country = norm(item.json.country).slice(0, 2) || null;
  const entry = { ref: item.json.ref ?? null };
  for (const v of variants(item.json.id, country)) {
    const key = country ? `${country}:${v}` : v;
    if (!index.has(key)) index.set(key, []);
    index.get(key).push(entry);
  }
}

const matches = [];
let cursor = null;
for (const page of $input.all()) {
  const body = page.json;
  if (typeof body.nextCursor === 'number') cursor = Math.max(cursor ?? 0, body.nextCursor);
  for (const record of body.records ?? []) {
    if (!record.registryId) continue;
    const country = norm(record.country).slice(0, 2);
    const hits = new Set();
    for (const v of variants(record.registryId, country)) {
      for (const key of [`${country}:${v}`, v]) for (const e of index.get(key) ?? []) hits.add(e);
    }
    if (hits.size) matches.push({ json: { matchedRefs: [...new Set([...hits].map((h) => h.ref).filter(Boolean))], ...record } });
  }
}

// Remember the position for the next scheduled run. Records that did not match are dropped here.
if (cursor != null) $getWorkflowStaticData('global').cursor = cursor;
return matches;
